         color: #b7f7d4;
       }

       button {
         width: 100%;
         margin-top: 1.25rem;
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.2rem;
         background: linear-gradient(135deg, var(--accent), #06b6d4);
         color: #ffffff;
         font: inherit;
         font-weight: 800;
         cursor: pointer;
         box-shadow: 0 14px 30px rgba(139, 92, 246, 0.32);
       }

       button:hover {
         filter: brightness(1.08);
       }

       button:focus-visible,
       input[type="checkbox"]:focus-visible {
         outline: 3px solid #f8fafc;
         outline-offset: 4px;
       }

       [hidden] {
         display: none;
       }

       @media (forced-colors: active) {
         body {
           background: Canvas;
           color: CanvasText;
         }

         .card,
         .form-field {
           background: Canvas;
           border-color: CanvasText;
         }

         .intro,
         .required-note,
         .helper {
           color: CanvasText;
         }

         .required-marker,
         .error {
           color: Mark;
         }

         button {
           background: ButtonFace;
           color: ButtonText;
           border: 2px solid ButtonText;
         }
       }
     </style>
   </head>
   <body>
     <main>
       <section class="card" aria-labelledby="form-title">
         <h1 id="form-title">Create your account</h1>
         <p class="intro">Review and accept the terms to continue.</p>

         <form id="consent-form" novalidate>
           <p class="required-note"><span aria-hidden="true">*</span> Required field</p>

           <div class="form-field">
             <input
               id="terms-consent"
               name="termsConsent"
               type="checkbox"
               required
               aria-describedby="terms-help terms-error"
             >
             <label for="terms-consent">
               I agree to the terms of use <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <p id="terms-help" class="helper">You must agree before submitting this form.</p>
             <p id="terms-error" class="error" hidden>Error: Agree to the terms of use to continue.</p>
           </div>

           <button type="submit">Accept and continue</button>
           <p id="form-status" class="status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#consent-form");
       const checkbox = document.querySelector("#terms-consent");
       const error = document.querySelector("#terms-error");
       const status = document.querySelector("#form-status");

       function setError(isInvalid) {
         checkbox.setAttribute("aria-invalid", String(isInvalid));
         error.hidden = !isInvalid;
       }

       checkbox.addEventListener("change", () => {
         if (checkbox.checked) {
           setError(false);
           status.textContent = "";
         }
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!checkbox.checked) {
           setError(true);
           status.textContent = "";
           checkbox.focus();
           return;
         }

         setError(false);
         status.textContent = "Terms accepted. You can continue.";
       });
     </script>
   </body>
 </html>

