const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axePath = require.resolve('axe-core/axe.min.js');
const pagePath = process.argv[2];

function summarize(violations) {
  return violations.map((violation) => ({
    id: violation.id,
    impact: violation.impact,
    tags: violation.tags,
    targets: violation.nodes.map((node) => node.target),
  }));
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.setContent(fs.readFileSync(pagePath, 'utf8'), { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });

  const initial = await page.evaluate(async () => await window.axe.run(document));
  await page.click('button[type="submit"]');
  const invalidFocusId = await page.evaluate(() => document.activeElement && document.activeElement.id);
  const invalid = await page.evaluate(async () => await window.axe.run(document));
  await browser.close();

  const wcagInitial = initial.violations.filter((v) => !v.tags.includes('best-practice'));
  const wcagInvalid = invalid.violations.filter((v) => !v.tags.includes('best-practice'));
  const result = {
    initial: summarize(wcagInitial),
    invalidState: summarize(wcagInvalid),
    invalidFocusId,
  };
  console.log(JSON.stringify(result, null, 2));
  if (wcagInitial.length || wcagInvalid.length || invalidFocusId !== 'terms-consent') {
    process.exit(1);
  }
})();
